pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 tosLength, uint256 vsLengthExtra) public {
        // tosLength >= 1, vsLengthExtra >= 0, so vs.length = tosLength + vsLengthExtra
        // Keep sizes manageable for fuzzer
        tosLength = bound(tosLength, 1, 20);
        vsLengthExtra = bound(vsLengthExtra, 0, 20);
        uint256 vsLength = tosLength + vsLengthExtra;

        address[] memory tos = new address[](tosLength);
        uint256[] memory vs = new uint256[](vsLength);
        for(uint i = 0; i < tosLength; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(i, "tos")))));
        }
        for(uint i = 0; i < vsLength; i++) {
            vs[i] = uint256(keccak256(abi.encodePacked(i, "vs")));
        }

        // Use a helper that never reverts and whose address is not address(0) or address(c)
        address callee = address(new AcceptingCallee());

        // Attempt the call; observe only whether c's transfer returned true without reverting
        bool ok;
        try c.transfer(callee, tos, vs) returns (bool result) {
            ok = result;
        } catch {
            ok = false;
        }

        // The reference implementation (loop bound tos.length) will always succeed (no out-of-bounds access).
        // The buggy version (loop bound vs.length) will revert (ok == false) when vsLength > tosLength,
        // because it accesses tos[i] for i >= tosLength, causing an out-of-bounds array access revert.
        // Thus the property: the call must never revert.
        assertTrue(ok);
    }
}

contract AcceptingCallee {
    fallback() external payable {
        // Accept any call without reverting
        assembly {
            mstore(0, 1)
            return(0, 32)
        }
    }
}

