contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address[] memory tos, uint[] memory vs) public {
        // The fuzzer supplies arrays; we make them admissible: non-empty and equal length.
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);

        // Use the contract itself as the target; the reference modifier should reject it.
        address target = address(c);

        bool ok = true;
        try c.transfer(target, tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference C always reverts when target == address(c); the mutant succeeds for some inputs.
        assertTrue(!ok);
    }
